-- Integration settings per product (docs/CRYPTO_SPINOFF_PLAN.md, step 2 item 8): each value is BitoCard's or Afrippa's,
-- set in that product's own admin. Every crypto setting moves to Afrippa, carried over as it is (never deleted);
-- everything else stays BitoCard's. Afrippa sets its own account for each service both use.
ALTER TABLE "integration_settings" ADD COLUMN "platform" "Platform" NOT NULL DEFAULT 'bitocard';
ALTER TABLE "integration_settings" DROP CONSTRAINT "integration_settings_pkey";
ALTER TABLE "integration_settings" ADD CONSTRAINT "integration_settings_pkey" PRIMARY KEY ("platform", "key");

UPDATE "integration_settings" SET "platform" = 'afrippa' WHERE "key" IN (
  'ALCHEMY_API_KEY', 'ALCHEMY_SANDBOX', 'ALCHEMY_WEBHOOK_SIGNING_KEY', 'ANKR_API_KEY', 'ANKR_SANDBOX', 'BLOCKCYPHER_SANDBOX',
  'BLOCKCYPHER_TOKEN', 'BLOCKCYPHER_WEBHOOK_TOKEN', 'BLOCKSTREAM_API_URL', 'BLOCKSTREAM_ENABLED', 'BLOCKSTREAM_SANDBOX', 'CHAINALYSIS_API_KEY',
  'CHAINALYSIS_API_URL', 'CHAINSTACK_ARBITRUM_URL', 'CHAINSTACK_BASE_URL', 'CHAINSTACK_BITCOIN_URL', 'CHAINSTACK_BSC_URL', 'CHAINSTACK_ETHEREUM_URL',
  'CHAINSTACK_OPTIMISM_URL', 'CHAINSTACK_POLYGON_URL', 'CHAINSTACK_SANDBOX', 'CHAINSTACK_SOLANA_URL', 'CHAINSTACK_TRON_URL', 'COINBASE_PRICE_URL',
  'COINGECKO_API_KEY', 'COINGECKO_API_URL', 'CRYPTO_PRICE_DIVERGENCE_BPS', 'CRYPTO_PRICE_SECONDARY', 'CRYPTO_SIGNER_SANDBOX', 'CRYPTO_SIGNER_SECRET',
  'CRYPTO_SIGNER_URL', 'CRYPTO_TEST_XPUB_BITCOIN', 'CRYPTO_TEST_XPUB_DOGECOIN', 'CRYPTO_TEST_XPUB_EVM', 'CRYPTO_TEST_XPUB_LITECOIN', 'CRYPTO_TEST_XPUB_TRON',
  'CRYPTO_XPUB_BITCOIN', 'CRYPTO_XPUB_DOGECOIN', 'CRYPTO_XPUB_EVM', 'CRYPTO_XPUB_LITECOIN', 'CRYPTO_XPUB_TRON', 'GETBLOCK_ARBITRUM_URL',
  'GETBLOCK_BASE_URL', 'GETBLOCK_BITCOIN_URL', 'GETBLOCK_BSC_URL', 'GETBLOCK_DOGECOIN_URL', 'GETBLOCK_ETHEREUM_URL', 'GETBLOCK_LITECOIN_URL',
  'GETBLOCK_OPTIMISM_URL', 'GETBLOCK_POLYGON_URL', 'GETBLOCK_SANDBOX', 'GETBLOCK_SOLANA_URL', 'GETBLOCK_TRON_URL', 'HELIUS_API_KEY',
  'HELIUS_SANDBOX', 'HELIUS_WEBHOOK_AUTH', 'INFURA_API_KEY', 'INFURA_SANDBOX', 'LITECOINSPACE_API_URL', 'LITECOINSPACE_ENABLED',
  'LITECOINSPACE_SANDBOX', 'MEMPOOL_API_URL', 'MEMPOOL_ENABLED', 'MEMPOOL_SANDBOX', 'MORALIS_ARBITRUM_URL', 'MORALIS_BASE_URL',
  'MORALIS_BSC_URL', 'MORALIS_ETHEREUM_URL', 'MORALIS_OPTIMISM_URL', 'MORALIS_POLYGON_URL', 'MORALIS_SANDBOX', 'MORALIS_STREAM_SECRET',
  'NODEREAL_API_KEY', 'NODEREAL_SANDBOX', 'QUICKNODE_ARBITRUM_URL', 'QUICKNODE_BASE_URL', 'QUICKNODE_BITCOIN_URL', 'QUICKNODE_BSC_URL',
  'QUICKNODE_ETHEREUM_URL', 'QUICKNODE_OPTIMISM_URL', 'QUICKNODE_POLYGON_URL', 'QUICKNODE_SANDBOX', 'QUICKNODE_SOLANA_URL', 'QUICKNODE_TRON_URL',
  'QUICKNODE_WEBHOOK_SECRET', 'TATUM_API_KEY', 'TATUM_SANDBOX', 'TATUM_WEBHOOK_SECRET', 'TRM_API_KEY', 'TRM_API_URL',
  'TRONGRID_API_KEY', 'TRONGRID_SANDBOX'
);
